"""Author nominal root/function declaration admission and ordered callbacks."""
from __future__ import annotations
import ast
from pathlib import Path
from hepta.hia_agent_assembly import render_assembly
from hepta.hia_opcodes import EFFECTS
from hepta.hia_schema import COMPOSITE_OPERATIONS_BY_SCHEMA, LEGACY_COMPOSITE_OPERATIONS
from tools.generate_hia_core_json_frontend import packed
from tools.generate_hia_instruction_policy import SOURCE as TRANSPORT_SOURCE
from tools.generate_hia_enum_match import BODY as MATCH_BODY
from tools.generate_hia_task_helpers import BODY as HELPER_BODY, PRIMITIVES
from tools.hia_native_value_graph import BODY as GRAPH_BODY
from tools.generate_hia_selfhost import Builder, compact_authoring_cfg, total_scalar_functions

MAGIC = int.from_bytes(b'HIANAD01', 'little')
INPUT_BYTES = 32 << 20
OUTPUT_BYTES = 1 << 20
WORKSPACE_BYTES = 40 << 20
FIELDS = ('schema', 'module', 'types', 'functions', 'name', 'params', 'returns',
          'effects', 'entry', 'blocks', 'return_loans', 'kind')
CONSTANTS = {'MAGIC': MAGIC, 'INPUT_BYTES': INPUT_BYTES, 'O_BYTES': OUTPUT_BYTES,
    'W_BYTES': WORKSPACE_BYTES, 'S': 4096, 'P': 8192, 'FN': 16384,
    'SOURCE_BASE': 1 << 20, 'N': (1 << 64) - 1, 'ABI': 0xfffffff1}
CONSTANTS.update({'F_' + key: index + 1 for index, key in enumerate(FIELDS)})
CONSTANTS['ROOT_KEYS'] = sum(1 << CONSTANTS['F_' + key] for key in ('schema','module','types','functions'))
CONSTANTS['FN_KEYS'] = sum(1 << CONSTANTS['F_' + key] for key in ('name','params','returns','effects','entry','blocks'))

BODY = r'''
def nominal_admission(s:readbuf, o:mutbuf, w:mutbuf) -> u32:
    if length(s) > INPUT_BYTES or length(o) < O_BYTES or length(w) < W_BYTES:
        return ABI
    i = 0
    while i < 64:
        put(w, S + i, 0)
        i = i + 8
    if get(o, 0) != MAGIC or get(o, 40) != 0 or get(o, 48) != 0 or get(o, 56) != 0:
        return ABI
    if a_validate(s, w) == 0:
        return ABI
    if get(w, P) == 0:
        if initialize(s, o, w) == 0:
            return ABI
    else:
        action = get(w, P + 16)
        if get(w, P) != MAGIC or action == 0:
            return ABI
        if get(o, 8) != get(w, P + 8) or get(o, 16) != action:
            return ABI
        if get(o, 24) != position(w) or get(o, 32) != item(w):
            return ABI
        if action != 5 and action != 9 and action != 11 and a_tag(s, 0) != 0:
            return ABI
        if advance(s, w, action) == 0:
            return ABI
    if get(w, S + 32) != 0:
        return ABI
    put(w, S + 24, 64)
    render(o, w)
    if get(w, S + 32) != 0:
        return ABI
    put(o, 0, MAGIC)
    put(o, 8, get(w, P + 128))
    put(o, 16, get(w, P + 16))
    put(o, 24, position(w))
    put(o, 32, item(w))
    put(o, 40, get(w, P + 8))
    put(o, 48, get(w, S + 24) - 64)
    put(o, 56, 0)
    return get(w, S + 24)

def initialize(s:readbuf, o:mutbuf, w:mutbuf) -> u64:
    if get(o, 8) != 0 or get(o, 16) != 0 or get(o, 24) != 0 or get(o, 32) != 0:
        return 0
    if a_tag(s, 0) != 5 or a_total(s, 0) != 3:
        return 0
    legacy = a_element(s, 0, 0)
    nonce = a_element(s, 0, 1)
    if a_tag(s, legacy) != 0 or a_tag(s, nonce) != 4 or a_size_of(s, nonce) != 32:
        return 0
    i = 0
    while i < 256:
        put(w, P + i, 0)
        i = i + 8
    put(w, P, MAGIC)
    capture(s, w, a_element(s, 0, 2))
    root(w)
    return 1

def capture(s:readbuf, w:mutbuf, document:u64) -> u64:
    put(w, P + 144, length(s))
    put(w, P + 136, SOURCE_BASE + document)
    i = 0
    while i < length(s):
        store(w, SOURCE_BASE + i, byte(s, i))
        i = i + 1
    return 0

def position(w:mutbuf) -> u64:
    action = get(w, P + 16)
    if action == 8:
        return get(w, P + 104)
    if action >= 4 and action <= 7:
        return get(w, P + 24)
    return 0

def item(w:mutbuf) -> u64:
    return choose(get(w, P + 16) == 5, get(w, P + 32), 0)

def request(w:mutbuf, action:u64) -> u64:
    put(w, P + 16, action)
    put(w, P + 8, get(w, P + 8) + 1)
    return 0

def refuse(w:mutbuf, error:u64) -> u64:
    put(w, P + 128, error)
    put(w, P + 16, 0)
    return 0

def missing(w:mutbuf, key:u64) -> u64:
    put(w, P + 160, key)
    return refuse(w, 15)

def unhashable(w:mutbuf, kind:u64, error:u64) -> u64:
    put(w, P + 160, kind)
    return refuse(w, error)

def fields(w:mutbuf, node:u64) -> u64:
    if tag(w, node) != 6:
        return 0
    result = 0
    at = node + 24
    i = 0
    while i < total(w, node):
        ident = field_id(w, at)
        if ident == 0 or (result & (1 << ident)) != 0:
            return 0
        result = result | (1 << ident)
        at = end(w, end(w, at))
        i = i + 1
    return result

def field(w:mutbuf, node:u64, wanted:u64) -> u64:
    if tag(w, node) != 6:
        return N
    at = node + 24
    i = 0
    while i < total(w, node):
        value = end(w, at)
        if field_id(w, at) == wanted:
            return value
        at = end(w, value)
        i = i + 1
    return N

def root(w:mutbuf) -> u64:
    doc = get(w, P + 136)
    if fields(w, doc) != ROOT_KEYS:
        return refuse(w, 1)
    schema = schema_id(w, field(w, doc, F_schema))
    if schema == 0:
        return refuse(w, 2)
    put(w, P + 40, schema)
    return request(w, 9)

def legacy_control(s:readbuf, w:mutbuf, second:bool) -> u64:
    if a_tag(s, 0) != 5 or a_total(s, 0) != 2:
        return 0
    flag = a_element(s, 0, 0)
    if a_tag(s, flag) != 1:
        return 0
    put(w, P + 48, byte(s, flag + 16))
    capture(s, w, a_element(s, 0, 1))
    schema = field(w, get(w, P + 136), F_schema)
    if second:
        if get(w, P + 48) == 0:
            if schema == N:
                missing(w, F_schema)
                return 1
            ident = schema_id(w, schema)
            if ident == 0:
                if tag(w, schema) == 5 or tag(w, schema) == 6:
                    unhashable(w, tag(w, schema), 17)
                else:
                    refuse(w, 16)
                return 1
            put(w, P + 40, ident)
        request(w, 1)
        return 1
    if get(w, P + 48) != 0:
        if schema == N:
            missing(w, F_schema)
            return 1
        if schema_id(w, schema) != 1:
            refuse(w, 3)
            return 1
    module = field(w, get(w, P + 136), F_module)
    if module == N:
        missing(w, F_module)
        return 1
    status = name_status(w, module)
    if status != 0:
        refuse(w, 3 + status)
    else:
        request(w, 10)
    return 1

def type_flags(w:mutbuf) -> u64:
    schema = field(w, get(w, P + 136), F_schema)
    if schema == N:
        return missing(w, F_schema)
    if tag(w, schema) == 5 or tag(w, schema) == 6:
        return unhashable(w, tag(w, schema), 18)
    put(w, P + 40, schema_id(w, schema))
    return request(w, 12)

def function_inventory(w:mutbuf) -> u64:
    functions = field(w, get(w, P + 136), F_functions)
    if functions == N:
        return missing(w, F_functions)
    if tag(w, functions) != 5 or total(w, functions) == 0 or total(w, functions) > 1024:
        return refuse(w, 6)
    put(w, P + 56, total(w, functions))
    put(w, P + 72, functions + 24)
    return request(w, 3)

def next_function(w:mutbuf) -> u64:
    node = get(w, P + 72)
    put(w, P + 64, node)
    wanted = FN_KEYS
    extra = get(w, P + 40) == 4 and field(w, node, F_return_loans) != N
    if extra:
        wanted = wanted | (1 << F_return_loans)
    if fields(w, node) != wanted:
        return refuse(w, choose(extra, 8, 7))
    name = field(w, node, F_name)
    status = name_status(w, name)
    if status != 0:
        return refuse(w, 8 + status)
    i = 0
    while i < get(w, P + 24):
        if same_text(w, name, get(w, FN + i * 8)) != 0:
            return refuse(w, 11)
        i = i + 1
    return request(w, 4)

def return_inventory(w:mutbuf) -> u64:
    returns = field(w, get(w, P + 64), F_returns)
    if tag(w, returns) != 5:
        return refuse(w, 12)
    put(w, P + 32, 0)
    put(w, P + 80, returns + 24)
    put(w, P + 88, total(w, returns))
    put(w, P + 96, 0)
    if total(w, returns) != 0:
        return request(w, 5)
    return after_returns(w)

def returned_type(s:readbuf, w:mutbuf) -> u64:
    if a_tag(s, 0) != 5 or a_total(s, 0) != 2:
        return 0
    kind = a_kind_id(s, a_element(s, 0, 0))
    flat = a_element(s, 0, 1)
    if kind == 0 or a_tag(s, flat) != 5 or a_total(s, flat) > 512:
        return 0
    if kind == 1 and a_total(s, flat) != 1:
        return 0
    at = flat + 24
    i = 0
    borrowed = 0
    while i < a_total(s, flat):
        typ = a_type_id(s, at)
        if typ == 0:
            return 0
        if a_loan(s, at) != 0:
            borrowed = 1
        at = a_end(s, at)
        i = i + 1
    if borrowed != 0 and (get(w, P + 40) != 4 or kind != 1):
        put(w, P + 96, 1)
    put(w, P + 32, get(w, P + 32) + 1)
    put(w, P + 80, end(w, get(w, P + 80)))
    if get(w, P + 32) < get(w, P + 88):
        request(w, 5)
    else:
        after_returns(w)
    return 1

def after_returns(w:mutbuf) -> u64:
    if get(w, P + 96) != 0:
        return refuse(w, 13)
    if get(w, P + 40) == 4:
        return request(w, 6)
    return effects(w)

def effects(w:mutbuf) -> u64:
    node = field(w, get(w, P + 64), F_effects)
    if tag(w, node) != 5:
        return refuse(w, 14)
    mask = 0
    at = node + 24
    i = 0
    while i < total(w, node):
        ident = effect_id(w, at)
        if ident == 0 or (mask & (1 << ident)) != 0:
            return refuse(w, 14)
        mask = mask | (1 << ident)
        at = end(w, at)
        i = i + 1
    return request(w, 7)

def bound(w:mutbuf) -> u64:
    node = get(w, P + 64)
    put(w, FN + get(w, P + 24) * 8, field(w, node, F_name))
    put(w, P + 72, end(w, node))
    put(w, P + 24, get(w, P + 24) + 1)
    if get(w, P + 24) < get(w, P + 56):
        return next_function(w)
    types = field(w, get(w, P + 136), F_types)
    if tag(w, types) != 5:
        put(w, S + 32, 1)
        return 0
    put(w, P + 112, types + 24)
    put(w, P + 120, total(w, types))
    return next_task(w)

def next_task(w:mutbuf) -> u64:
    while get(w, P + 104) < get(w, P + 120):
        node = get(w, P + 112)
        kind = field(w, node, F_kind)
        if kind == N:
            put(w, S + 32, 1)
            return 0
        if task_kind(w, kind) != 0:
            return request(w, 8)
        put(w, P + 104, get(w, P + 104) + 1)
        put(w, P + 112, end(w, node))
    put(w, P + 16, 0)
    return 0

def advance(s:readbuf, w:mutbuf, action:u64) -> u64:
    if action == 1:
        type_flags(w)
    elif action == 2:
        function_inventory(w)
    elif action == 3:
        next_function(w)
    elif action == 4:
        return_inventory(w)
    elif action == 5:
        return returned_type(s, w)
    elif action == 6:
        effects(w)
    elif action == 7:
        bound(w)
    elif action == 8:
        put(w, P + 104, get(w, P + 104) + 1)
        put(w, P + 112, end(w, get(w, P + 112)))
        next_task(w)
    elif action == 9:
        return legacy_control(s, w, False)
    elif action == 10:
        request(w, 11)
    elif action == 11:
        return legacy_control(s, w, True)
    elif action == 12:
        request(w, 2)
    else:
        return 0
    return 1

def graph_boolean(o:mutbuf, w:mutbuf, flag:bool) -> u64:
    graph_word(o, w, 1)
    graph_word(o, w, 1)
    append_byte(o, w, choose(flag, 1, 0))
    return 0

def graph_zero(o:mutbuf, w:mutbuf) -> u64:
    graph_word(o, w, 2)
    graph_word(o, w, 1)
    append_byte(o, w, 48)
    return 0

def graph_held_name(o:mutbuf, w:mutbuf, node:u64) -> u64:
    graph_word(o, w, 4)
    graph_word(o, w, size_of(w, node))
    i = 0
    while i < size_of(w, node):
        append_byte(o, w, byte(w, node + 16 + i))
        i = i + 1
    return 0

def render(o:mutbuf, w:mutbuf) -> u64:
    action = get(w, P + 16)
    error = get(w, P + 128)
    if error == 15:
        if get(w, P + 160) == F_schema:
            graph_string(o, w, L_schema)
        elif get(w, P + 160) == F_module:
            graph_string(o, w, L_module)
        else:
            graph_string(o, w, L_functions)
    elif error == 16:
        graph_ref(o, w, field(w, get(w, P + 136), F_schema) - SOURCE_BASE)
    elif error == 17 or error == 18:
        if get(w, P + 160) == 5:
            graph_string(o, w, L_list)
        else:
            graph_string(o, w, L_dict)
    elif action == 1:
        operation_names(o, w)
    elif action == 12:
        root = graph_begin(o, w, 6, 2)
        graph_string(o, w, L_recursive)
        graph_boolean(o, w, get(w, P + 40) != 1)
        graph_string(o, w, L_partial)
        graph_boolean(o, w, get(w, P + 40) >= 3)
        graph_end(o, w, root)
    elif action == 10:
        root = graph_begin(o, w, 6, 2)
        graph_string(o, w, L_serial)
        graph_zero(o, w)
        graph_string(o, w, L_slots)
        graph_zero(o, w)
        graph_end(o, w, root)
    elif action == 2:
        graph_boolean(o, w, get(w, P + 40) == 4)
    elif action == 6 or action == 7:
        graph_held_name(o, w, field(w, get(w, P + 64), F_name))
    else:
        graph_null(o, w)
    return 0
'''


def source_program():
    common={'word','put','get','tag','size_of','end','total','element','text_is','same_text'}
    raw=TRANSPORT_SOURCE.replace('    DISPATCH','    pass').replace('1048576','8388608')
    originals=[n for n in ast.parse(raw).body if isinstance(n,ast.FunctionDef) and n.name in common]
    class Mutable(ast.NodeTransformer):
        def visit_arg(self,node):
            if isinstance(node.annotation,ast.Name) and node.annotation.id=='readbuf':
                node.annotation=ast.Name(id='mutbuf',ctx=ast.Load())
            return node
    original_nodes=[Mutable().visit(n) for n in originals]
    incoming=common-{'put','get'}|{'validate'}
    class Incoming(ast.NodeTransformer):
        def visit_FunctionDef(self,node):
            node.name='a_'+node.name
            return self.generic_visit(node)
        def visit_Name(self,node):
            if node.id in incoming:node.id='a_'+node.id
            return node
    incoming_nodes=[Incoming().visit(n) for n in ast.parse(raw).body
                    if isinstance(n,ast.FunctionDef) and n.name in incoming]
    own=ast.parse(BODY)
    own.body+=original_nodes+incoming_nodes
    own.body += [Mutable().visit(n) for n in ast.parse(MATCH_BODY).body
                 if isinstance(n,ast.FunctionDef) and n.name in {'prefix','name_status'}]
    own.body += ast.parse(GRAPH_BODY).body
    own.body += [n for n in ast.parse(HELPER_BODY).body if isinstance(n,ast.FunctionDef) and n.name in {'append_byte','emit'}]
    literals={'L_'+key:packed(value) for key,value in [
        ('operations','nominal_operations'),('recursive','recursive_chain'),
        ('partial','partial_records'),('serial','serial'),('slots','value_slots'),
        ('schema','schema'),('module','module'),('functions','functions'),('list','list'),('dict','dict')]}
    class Expand(ast.NodeTransformer):
        def visit_Name(self,node):
            return ast.Constant(CONSTANTS[node.id]) if node.id in CONSTANTS else node
        def visit_Call(self,node):
            node=self.generic_visit(node);args=[]
            for arg in node.args:
                if isinstance(arg,ast.Name) and arg.id in literals:
                    args.extend(ast.Constant(value) for value in literals[arg.id])
                else:args.append(arg)
            node.args=args;return node
    own=Expand().visit(own)
    suffix=[]
    tables=[('field_id','mutbuf',enumerate(FIELDS,1),'text_is'),
            ('schema_id','mutbuf',enumerate(COMPOSITE_OPERATIONS_BY_SCHEMA,1),'text_is'),
            ('effect_id','mutbuf',enumerate(sorted(EFFECTS),1),'text_is'),
            ('task_kind','mutbuf',[(1,'task')],'text_is'),
            ('a_kind_id','readbuf',enumerate(('primitive','record','enum','task','partial_record'),1),'a_text_is'),
            ('a_type_id','readbuf',enumerate(PRIMITIVES,1),'a_text_is'),
            ('a_loan','readbuf',[(1,'readbuf'),(1,'mutbuf')],'a_text_is')]
    for name,kind,values,predicate in tables:
        suffix.append('def '+name+'(s:'+kind+', node:u64) -> u64:')
        for ident,value in values:
            suffix += ['    if '+predicate+'(s, node, '+', '.join(map(str,packed(value)))+') != 0:',
                       '        return '+str(ident)]
        suffix.append('    return 0')
    suffix.append('def operation_names(o:mutbuf, w:mutbuf) -> u64:')
    selections=[('get(w, 8192 + 48) != 0',LEGACY_COMPOSITE_OPERATIONS)]
    selections += [('get(w, 8192 + 40) == '+str(i),values)
                   for i,values in enumerate(COMPOSITE_OPERATIONS_BY_SCHEMA.values(),1)]
    for condition,values in selections:
        suffix += ['    if '+condition+':','        start = graph_begin(o, w, 5, '+str(len(values))+')']
        for value in sorted(values):suffix.append('        graph_string(o, w, '+', '.join(map(str,packed(value)))+')')
        suffix += ['        graph_end(o, w, start)','        return 0']
    suffix += ['    put(w, 4096 + 32, 1)','    return 0']
    return ast.unparse(ast.fix_missing_locations(own))+'\n'+'\n'.join(suffix)+'\n'


def document():
    nodes=ast.parse(source_program()).body
    assert len({n.name for n in nodes})==len(nodes)
    names={n.name:'f'+str(i) for i,n in enumerate(nodes)}
    sigs={n.name:([a.annotation.id for a in n.args.args],n.returns.id) for n in nodes}
    total=total_scalar_functions(nodes);functions=[]
    for node in nodes:
        builder=Builder(node,names,sigs,total);builder.statements(node.body)
        functions.append({'name':names[node.name],'params':[builder.param(p) for p in builder.params],
            'returns':[builder.returns],'effects':['read','write','trap'],'entry':'b0','blocks':builder.blocks})
    return compact_authoring_cfg({'schema':'hepta.hia.program.v8','module':'nominal_admission','functions':functions})


if __name__=='__main__':
    path=Path(__file__).resolve().parents[1]/'examples/hia_bootstrap/nominal_admission.hepta'
    path.write_text(render_assembly(document()));print(path.name,path.stat().st_size)

"""Author complete nominal module aggregation and export policy in HIA.

The owner requests original function producers in order, then observes their
complete retained helper suffix. Inventory refusal and sorted scalar exports
remain after all function production. Complete objects cross only the generic
external-value pool boundary; their instructions are not reconstructed here.
"""
from __future__ import annotations
import ast
from pathlib import Path
from hepta.hia_agent_assembly import render_assembly
from hepta.hia_opcodes import SCALARS
from tools.generate_hia_core_json_frontend import packed
from tools.generate_hia_instruction_policy import SOURCE as TRANSPORT_SOURCE
from tools.generate_hia_enum_match import BODY as MATCH_BODY
from tools.generate_hia_task_helpers import BODY as HELPER_BODY, PRIMITIVES
from tools.hia_native_value_graph import BODY as GRAPH_BODY
from tools.generate_hia_selfhost import Builder, compact_authoring_cfg, total_scalar_functions

MAGIC = int.from_bytes(b'HIANMD01', 'little')
INPUT_BYTES = 256 << 20
OUTPUT_BYTES = 8 << 20
WORKSPACE_BYTES = 8 << 20
CONSTANTS = {'MAGIC': MAGIC, 'INPUT_BYTES': INPUT_BYTES, 'O_BYTES': OUTPUT_BYTES,
    'W_BYTES': WORKSPACE_BYTES, 'S': 4096, 'P': 8192, 'T': 16384,
    'SG': 4210688, 'FT': 4218880, 'N': (1 << 64) - 1, 'ABI': 0xfffffff1}

BODY = r'''
def nominal_module(s:readbuf, o:mutbuf, w:mutbuf) -> u32:
    if length(s) > INPUT_BYTES or length(o) < O_BYTES or length(w) < W_BYTES:
        return ABI
    i = 0
    while i < 64:
        put(w, S + i, 0)
        i = i + 8
    if get(o, 0) != MAGIC or get(o, 56) != 0:
        return ABI
    if get(w, P) == 0:
        if initialize(s, o, w) == 0:
            return ABI
    else:
        if get(w, P) != MAGIC or get(w, P + 16) == 4:
            return ABI
        if get(o, 8) != get(w, P + 8) or get(o, 16) != get(w, P + 16):
            return ABI
        if continuation(s, o, w) == 0:
            return ABI
    if get(w, S + 32) != 0:
        return ABI
    put(w, S + 24, 64)
    if get(w, P + 16) == 4 and get(w, P + 64) == 0:
        render(s, o, w)
    else:
        graph_null(o, w)
    if get(w, S + 32) != 0:
        return ABI
    put(o, 0, MAGIC)
    put(o, 8, get(w, P + 64))
    put(o, 16, choose(get(w, P + 16) == 4, 0, get(w, P + 16)))
    put(o, 24, get(w, P + 24))
    put(o, 32, get(w, P + 8))
    put(o, 40, get(w, S + 24) - 64)
    put(o, 48, get(w, P + 32) + 1)
    put(o, 56, 0)
    return get(w, S + 24)

def metadata(s:readbuf, w:mutbuf, capture:u64) -> u64:
    if tag(s, 0) != 5 or total(s, 0) < 4:
        return 0
    at = 24
    stop = end(s, element(s, 0, 3))
    if stop - 24 > 512:
        return 0
    if capture == 0 and get(w, P + 96) != stop - 24:
        return 0
    put(w, P + 96, stop - 24)
    while at < stop:
        if capture != 0:
            store(w, P + 256 + at - 24, byte(s, at))
        elif byte(w, P + 256 + at - 24) != byte(s, at):
            return 0
        at = at + 1
    return 1

def initialize(s:readbuf, o:mutbuf, w:mutbuf) -> u64:
    if get(o, 8) != 0 or get(o, 16) != 0 or get(o, 24) != 0 or get(o, 32) != 0 or get(o, 40) != 0 or get(o, 48) != 0:
        return 0
    if validate(s, w) == 0:
        return 0
    if tag(s, 0) != 5 or total(s, 0) != 4:
        return 0
    schema = schema_id(s, element(s, 0, 0))
    count = unsigned(s, element(s, 0, 2))
    if schema == 0 or name_status(s, element(s, 0, 1)) != 0 or count == 0 or count > 1024:
        return 0
    nonce = element(s, 0, 3)
    if tag(s, nonce) != 4 or size_of(s, nonce) != 32:
        return 0
    i = 0
    while i < 128:
        put(w, P + i, 0)
        i = i + 8
    put(w, P, MAGIC)
    put(w, P + 8, 1)
    put(w, P + 16, 1)
    put(w, P + 32, count)
    if metadata(s, w, 1) == 0:
        return 0
    put(w, P + 88, schema)
    return 1

def continuation(s:readbuf, o:mutbuf, w:mutbuf) -> u64:
    if validate(s, w) == 0 or metadata(s, w, 0) == 0:
        return 0
    if get(w, P + 16) != 3 and total(s, 0) != 4:
        return 0
    if get(w, P + 16) == 1:
        return accept_function(o, w)
    if get(w, P + 16) == 2:
        return accept_helpers(o, w)
    if get(w, P + 16) == 3:
        if get(o, 24) != 0 or get(o, 32) != 0 or get(o, 40) != 0 or get(o, 48) != 0:
            return 0
        if total(s, 0) != 6 or signatures(s, w) == 0:
            return 0
        put(w, P + 16, 4)
        return 1
    return 0

def accept_function(o:mutbuf, w:mutbuf) -> u64:
    index = get(w, P + 24)
    if get(o, 24) != index or get(o, 32) != index or get(o, 48) != 0:
        return 0
    put(w, FT + index * 8, get(o, 32))
    if get(o, 40) > 4096:
        put(w, P + 48, 1)
    put(w, P + 8, get(w, P + 8) + 1)
    put(w, P + 24, index + 1)
    if index + 1 == get(w, P + 32):
        put(w, P + 16, 2)
        put(w, P + 24, 0)
    return 1

def accept_helpers(o:mutbuf, w:mutbuf) -> u64:
    count = get(o, 40)
    if get(o, 24) != 0 or get(o, 32) != get(w, P + 32):
        return 0
    if count > 262144 or get(o, 48) != count * 8 or 64 + count * 8 > O_BYTES:
        return 0
    put(w, FT + get(w, P + 32) * 8, get(o, 32))
    if count > 1024 - get(w, P + 32) or get(w, P + 48) != 0:
        put(w, P + 64, 1)
        put(w, P + 16, 4)
        return 1
    i = 0
    while i < count:
        if get(o, 64 + i * 8) > 4096:
            put(w, P + 64, 1)
            put(w, P + 16, 4)
            return 1
        i = i + 1
    put(w, P + 8, get(w, P + 8) + 1)
    put(w, P + 24, 0)
    put(w, P + 16, 3)
    return 1

def descriptor_ok(s:readbuf, node:u64) -> u64:
    if tag(s, node) != 5 or total(s, node) != 2:
        return 0
    kind = kind_id(s, element(s, node, 0))
    flat = element(s, node, 1)
    if kind == 0 or tag(s, flat) != 5 or total(s, flat) > 512:
        return 0
    if kind == 1 and total(s, flat) != 1:
        return 0
    at = flat + 24
    i = 0
    while i < total(s, flat):
        if type_id(s, at) == 0:
            return 0
        at = end(s, at)
        i = i + 1
    return 1

def type_list(s:readbuf, w:mutbuf, node:u64) -> u64:
    if tag(s, node) != 5 or total(s, node) > 262144:
        return 0
    result = 1
    at = node + 24
    i = 0
    while i < total(s, node):
        ident = unsigned(s, at)
        if ident >= get(w, P + 40):
            return 0
        descriptor = get(w, T + ident * 8)
        if kind_id(s, element(s, descriptor, 0)) != 1:
            result = 2
        elif scalar_id(s, element(s, element(s, descriptor, 1), 0)) == 0:
            result = 2
        at = end(s, at)
        i = i + 1
    return result

def before(s:readbuf, a:u64, b:u64) -> u64:
    i = 0
    count = size_of(s, a)
    if size_of(s, b) < count:
        count = size_of(s, b)
    while i < count:
        left = byte(s, a + 16 + i)
        right = byte(s, b + 16 + i)
        if left != right:
            return choose(left < right, 1, 0)
        i = i + 1
    return choose(size_of(s, a) < size_of(s, b), 1, 0)

def signatures(s:readbuf, w:mutbuf) -> u64:
    types = element(s, 0, 4)
    rows = element(s, 0, 5)
    if tag(s, types) != 5 or tag(s, rows) != 5 or total(s, types) > 524288 or total(s, rows) > 1024:
        return 0
    put(w, P + 40, total(s, types))
    at = types + 24
    i = 0
    while i < total(s, types):
        if descriptor_ok(s, at) == 0:
            return 0
        put(w, T + i * 8, at)
        at = end(s, at)
        i = i + 1
    at = rows + 24
    i = 0
    count = 0
    while i < total(s, rows):
        if tag(s, at) != 5 or total(s, at) != 3:
            return 0
        name = element(s, at, 0)
        if name_status(s, name) != 0:
            return 0
        params = type_list(s, w, element(s, at, 1))
        returns = type_list(s, w, element(s, at, 2))
        if params == 0 or returns == 0:
            return 0
        if params == 1 and returns == 1:
            j = count
            while j > 0 and before(s, name, get(w, SG + (j - 1) * 8)) != 0:
                put(w, SG + j * 8, get(w, SG + (j - 1) * 8))
                j = j - 1
            put(w, SG + j * 8, name)
            count = count + 1
        at = end(s, at)
        i = i + 1
    put(w, P + 80, count)
    return 1

def graph_pool_concat(o:mutbuf, w:mutbuf, originals:u64, count:u64) -> u64:
    graph_word(o, w, 11)
    graph_word(o, w, 8 + count * 8)
    graph_word(o, w, count)
    i = 0
    while i < count:
        graph_word(o, w, get(w, originals + i * 8))
        i = i + 1
    return 0

def render(s:readbuf, o:mutbuf, w:mutbuf) -> u64:
    root = graph_begin(o, w, 6, 4)
    graph_string(o, w, L_schema)
    schema = get(w, P + 88)
    if schema == 1:
        graph_string(o, w, L_v6)
    elif schema == 4:
        graph_string(o, w, L_v8)
    else:
        graph_string(o, w, L_v7)
    graph_string(o, w, L_module)
    graph_ref(o, w, element(s, 0, 1))
    graph_string(o, w, L_exports)
    exports = graph_begin(o, w, 5, get(w, P + 80))
    i = 0
    while i < get(w, P + 80):
        graph_ref(o, w, get(w, SG + i * 8))
        i = i + 1
    graph_end(o, w, exports)
    graph_string(o, w, L_functions)
    graph_pool_concat(o, w, FT, get(w, P + 32) + 1)
    graph_end(o, w, root)
    return 0
'''


def source_program():
    literals = {'L_' + key: packed(value) for key, value in
                [('schema','schema'),('module','module'),('exports','exports'),('functions','functions'),
                 ('v6','hepta.hia.program.v6'),('v7','hepta.hia.program.v7'),('v8','hepta.hia.program.v8')]}
    class Expand(ast.NodeTransformer):
        def visit_Name(self, node):
            return ast.Constant(CONSTANTS[node.id]) if node.id in CONSTANTS else node
        def visit_Call(self, node):
            node = self.generic_visit(node); args=[]
            for arg in node.args:
                if isinstance(arg, ast.Name) and arg.id in literals:
                    args.extend(ast.Constant(value) for value in literals[arg.id])
                else: args.append(arg)
            node.args=args;return node
    own=ast.parse(BODY)
    common={'validate','word','put','get','tag','size_of','end','total','element','text_is','same_text'}
    raw=TRANSPORT_SOURCE.replace('    DISPATCH','    pass').replace('1048576','8388608')
    own.body.extend(n for n in ast.parse(raw).body if isinstance(n,ast.FunctionDef) and n.name in common)
    shared={'unsigned','prefix','name_status'}
    raw=MATCH_BODY.replace('if value > 262144:', 'if value > 524288:')
    own.body.extend(n for n in ast.parse(raw).body if isinstance(n,ast.FunctionDef) and n.name in shared)
    own.body.extend(ast.parse(GRAPH_BODY).body)
    own.body.extend(n for n in ast.parse(HELPER_BODY).body if isinstance(n,ast.FunctionDef) and n.name in {'append_byte','emit'})
    own=Expand().visit(own);suffix=[]
    for fn,values in [('type_id',enumerate(PRIMITIVES,1)),('scalar_id',enumerate(sorted(SCALARS),1)),
        ('kind_id',enumerate(('primitive','record','enum','task','partial_record'),1)),
        ('schema_id',enumerate(('hepta.hia.composite.v1','hepta.hia.composite.v2','hepta.hia.composite.v3','hepta.hia.composite.v4'),1))]:
        suffix.append('def '+fn+'(s:readbuf, node:u64) -> u64:')
        for ident,value in values:
            suffix+=['    if text_is(s, node, '+', '.join(map(str,packed(value)))+') != 0:', '        return '+str(ident)]
        suffix+=['    return 0']
    return ast.unparse(ast.fix_missing_locations(own))+'\n'+'\n'.join(suffix)+'\n'


def document():
    nodes=ast.parse(source_program()).body
    assert len({n.name for n in nodes})==len(nodes)
    names={n.name:'f'+str(i) for i,n in enumerate(nodes)}
    sigs={n.name:([a.annotation.id for a in n.args.args],n.returns.id) for n in nodes}
    total=total_scalar_functions(nodes);functions=[]
    for n in nodes:
        b=Builder(n,names,sigs,total);b.statements(n.body)
        functions.append({'name':names[n.name],'params':[b.param(p) for p in b.params],
            'returns':[b.returns],'effects':['read','write','trap'],'entry':'b0','blocks':b.blocks})
    return compact_authoring_cfg({'schema':'hepta.hia.program.v8','module':'nominal_module','functions':functions})


if __name__=='__main__':
    path=Path(__file__).resolve().parents[1]/'examples/hia_bootstrap/nominal_module.hepta'
    path.write_text(render_assembly(document()));print(path.name,path.stat().st_size)

"""Author complete nominal jump, branch, return and trap policy in HIA.

HIA chooses complete logical Core terms. Generic source references and array
concatenations retain repeated aliases without a smaller flattened-output cap.
The independent original elaborator remains available only when unselected.
"""
from __future__ import annotations

import ast
from pathlib import Path

from hepta.hia_agent_assembly import render_assembly
from tools.generate_hia_core_json_frontend import packed
from tools.generate_hia_instruction_policy import SOURCE as TRANSPORT_SOURCE
from tools.generate_hia_enum_match import BODY as MATCH_BODY
from tools.generate_hia_task_helpers import BODY as HELPER_BODY, PRIMITIVES
from tools.hia_native_value_graph import BODY as GRAPH_BODY
from tools.generate_hia_selfhost import Builder, compact_authoring_cfg, total_scalar_functions

MAGIC = int.from_bytes(b'HIANTM01', 'little')
INPUT_BYTES = 256 << 20
OUTPUT_BYTES = 16 << 20
WORKSPACE_BYTES = 32 << 20
CONSTANTS = {
    'MAGIC': MAGIC, 'INPUT_BYTES': INPUT_BYTES, 'O_BYTES': OUTPUT_BYTES,
    'W_BYTES': WORKSPACE_BYTES, 'S': 4096, 'T': 8192,
    'EV': 4202496, 'EH': 6299648, 'MARK': 10493952,
    'VF': 12591104, 'UNIQUE': 14688256, 'SG': 16785408,
    'HEAP': 16826368, 'N': (1 << 64) - 1, 'ABI': 0xfffffff1,
}

BODY = r'''
def nominal_terminators(s:readbuf, o:mutbuf, w:mutbuf) -> u32:
    if length(s) > INPUT_BYTES or length(w) < W_BYTES or length(o) < O_BYTES:
        return ABI
    if validate(s, w) == 0:
        return ABI
    if tag(s, 0) != 5 or total(s, 0) != 6:
        return ABI
    i = 0
    while i < 256:
        put(w, S + i, 0)
        i = i + 8
    put(w, S + 16, HEAP)
    put(w, S + 96, 1)
    if admit(s, w) == 0:
        return ABI
    lower(s, w)
    if get(w, S + 32) != 0:
        return ABI
    put(w, S + 24, 64)
    i = 0
    while i < get(w, S + 80):
        graph_word(o, w, get(w, VF + i * 8))
        i = i + 1
    if get(w, S + 8) != 0 or get(w, S + 88) != 0:
        graph_null(o, w)
    else:
        render(s, o, w)
    if get(w, S + 32) != 0:
        return ABI
    put(o, 0, MAGIC)
    put(o, 8, get(w, S + 8))
    put(o, 16, get(w, S))
    put(o, 24, get(w, S + 24) - 64)
    put(o, 32, get(w, S + 88))
    put(o, 40, get(w, S + 96))
    put(o, 48, get(w, S + 80))
    put(o, 56, 0)
    return get(w, S + 24)

def keys(s:readbuf, node:u64, mask:u64, count:u64) -> u64:
    if tag(s, node) != 6 or total(s, node) != count:
        return 0
    at = node + 24
    seen = 0
    i = 0
    while i < count:
        ident = field_id(s, at)
        if ident == 0 or (seen & ident) != 0:
            return 0
        seen = seen | ident
        at = end(s, end(s, at))
        i = i + 1
    return choose(seen == mask, 1, 0)

def descriptor_ok(s:readbuf, node:u64) -> u64:
    if tag(s, node) != 5 or total(s, node) != 3:
        return 0
    kind = kind_id(s, element(s, node, 0))
    flat = flat_node(s, node)
    if kind == 0 or tag(s, flat) != 5 or total(s, flat) > 512:
        return 0
    if tag(s, element(s, node, 2)) != 1:
        return 0
    if kind == 1 and total(s, flat) != 1:
        return 0
    at = flat + 24
    i = 0
    while i < total(s, flat):
        if type_id(s, at) == 0:
            return 0
        at = end(s, at)
        i = i + 1
    return 1

def value_id(s:readbuf, w:mutbuf, index:u64) -> u64:
    return unsigned(s, element(s, get(w, EV + index * 8), 5))

def same_alias(s:readbuf, left:u64, right:u64) -> u64:
    if unsigned(s, element(s, left, 1)) != unsigned(s, element(s, right, 1)):
        return 0
    if truth(s, element(s, left, 3)) != truth(s, element(s, right, 3)):
        return 0
    if truth(s, element(s, left, 4)) != truth(s, element(s, right, 4)):
        return 0
    a = element(s, left, 2)
    b = element(s, right, 2)
    if total(s, a) != total(s, b):
        return 0
    x = a + 24
    y = b + 24
    i = 0
    while i < total(s, a):
        if same_text(s, x, y) == 0:
            return 0
        x = end(s, x)
        y = end(s, y)
        i = i + 1
    return 1

def admit_values(s:readbuf, w:mutbuf, values:u64) -> u64:
    count = total(s, values)
    capacity = 1
    while capacity < count * 2:
        capacity = capacity * 2
    put(w, S + 64, capacity)
    i = 0
    while i < capacity:
        put(w, EH + i * 8, 0)
        i = i + 1
    node = values + 24
    slots = 0
    i = 0
    while i < count:
        if tag(s, node) != 5 or total(s, node) != 6:
            return 0
        name = element(s, node, 0)
        ident = unsigned(s, element(s, node, 1))
        names = element(s, node, 2)
        if name_status(s, name) != 0 or ident >= get(w, S + 48) or tag(s, names) != 5:
            return 0
        if tag(s, element(s, node, 3)) != 1 or tag(s, element(s, node, 4)) != 1:
            return 0
        if total(s, names) != type_width(s, typename(s, w, ident)):
            return 0
        slots = slots + total(s, names)
        if slots > 32768:
            return 0
        at = names + 24
        j = 0
        while j < total(s, names):
            if name_status(s, at) == 1:
                return 0
            at = end(s, at)
            j = j + 1
        sid = unsigned(s, element(s, node, 5))
        if sid > get(w, S + 80):
            return 0
        if sid == get(w, S + 80):
            put(w, UNIQUE + sid * 8, node)
            put(w, VF + sid * 8, truth(s, element(s, node, 4)))
            put(w, S + 80, sid + 1)
        else:
            if same_alias(s, node, get(w, UNIQUE + sid * 8)) == 0:
                return 0
        put(w, EV + i * 8, node)
        put(w, MARK + i * 8, 0)
        slot = hash_name(s, name) & (capacity - 1)
        while get(w, EH + slot * 8) != 0:
            previous = get(w, EV + (get(w, EH + slot * 8) - 1) * 8)
            if same_text(s, name, element(s, previous, 0)) != 0:
                return 0
            slot = (slot + 1) & (capacity - 1)
        put(w, EH + slot * 8, i + 1)
        node = end(s, node)
        i = i + 1
    return 1

def type_inventory(s:readbuf, w:mutbuf, node:u64) -> u64:
    if tag(s, node) != 5 or total(s, node) > 262144:
        return 0
    at = node + 24
    i = 0
    while i < total(s, node):
        if unsigned(s, at) >= get(w, S + 48):
            return 0
        at = end(s, at)
        i = i + 1
    return 1

def admit(s:readbuf, w:mutbuf) -> u64:
    serial = unsigned(s, element(s, 0, 0))
    if serial > 8192:
        return 0
    put(w, S, serial)
    types = element(s, 0, 2)
    values = element(s, 0, 3)
    signatures = element(s, 0, 4)
    if tag(s, types) != 5 or tag(s, values) != 5 or tag(s, signatures) != 5:
        return 0
    tc = total(s, types)
    ec = total(s, values)
    sc = total(s, signatures)
    if tc > 524288 or ec > 262144 or sc > 4096:
        return 0
    put(w, S + 48, tc)
    put(w, S + 56, ec)
    put(w, S + 72, sc)
    node = types + 24
    i = 0
    while i < tc:
        put(w, T + i * 8, node)
        if descriptor_ok(s, node) == 0:
            return 0
        node = end(s, node)
        i = i + 1
    if admit_values(s, w, values) == 0:
        return 0
    node = signatures + 24
    i = 0
    while i < sc:
        if tag(s, node) != 5 or total(s, node) != 2:
            return 0
        if name_status(s, element(s, node, 0)) != 0:
            return 0
        if type_inventory(s, w, element(s, node, 1)) == 0:
            return 0
        put(w, SG + i * 8, node)
        node = end(s, node)
        i = i + 1
    return type_inventory(s, w, element(s, 0, 5))

def admitted_value(s:readbuf, w:mutbuf, name:u64) -> u64:
    if name_check(s, w, name, 4) == 0:
        return N
    index = env_lookup(s, w, name)
    if index == N:
        refuse(w, 6)
        return N
    if get(w, VF + value_id(s, w, index) * 8) != 0:
        refuse(w, 7)
        return N
    return index

def names_check(s:readbuf, w:mutbuf, names:u64, first:u64) -> u64:
    if tag(s, names) != 5:
        refuse(w, first)
        return 0
    at = names + 24
    i = 0
    while i < total(s, names):
        if name_status(s, at) == 1:
            refuse(w, first + 1)
            return 0
        at = end(s, at)
        i = i + 1
    return 1

def live(s:readbuf, w:mutbuf, index:u64) -> u64:
    node = get(w, EV + index * 8)
    return choose(linear(s, typename(s, w, env_type(s, w, index))) != 0 and truth(s, element(s, node, 3)) == 0 and get(w, VF + value_id(s, w, index) * 8) == 0, 1, 0)

def find_signature(s:readbuf, w:mutbuf, target:u64) -> u64:
    i = 0
    while i < get(w, S + 72):
        node = get(w, SG + i * 8)
        if same_text(s, target, element(s, node, 0)) != 0:
            return element(s, node, 1)
        i = i + 1
    return N

def same_types(s:readbuf, w:mutbuf, actual:u64, count:u64, expected:u64) -> u64:
    if count != total(s, expected):
        return 0
    at = expected + 24
    i = 0
    while i < count:
        if type_equal(s, w, env_type(s, w, get(w, actual + i * 8)), unsigned(s, at)) == 0:
            return 0
        at = end(s, at)
        i = i + 1
    return 1

def edge_values(s:readbuf, w:mutbuf, names:u64) -> u64:
    count = total(s, names)
    vector = allocate(w, count * 8)
    if get(w, S + 32) != 0:
        return N
    epoch = get(w, S + 192) + 1
    put(w, S + 192, epoch)
    at = names + 24
    i = 0
    while i < count:
        index = admitted_value(s, w, at)
        if index == N:
            return N
        if linear(s, typename(s, w, env_type(s, w, index))) != 0:
            if get(w, MARK + index * 8) == epoch:
                refuse(w, 15)
                return N
            put(w, MARK + index * 8, epoch)
        put(w, vector + i * 8, index)
        at = end(s, at)
        i = i + 1
    i = 0
    while i < get(w, S + 56):
        if live(s, w, i) != 0 and get(w, MARK + i * 8) != epoch:
            refuse(w, 16)
            return N
        i = i + 1
    return vector

def lower_edge(s:readbuf, w:mutbuf, raw:u64, outer:u64, destination:u64) -> u64:
    if outer == 0 and keys(s, raw, 6, 2) == 0:
        return refuse(w, 9)
    target = field(s, raw, 2)
    if name_check(s, w, target, 10) == 0:
        return 0
    names = field(s, raw, 4)
    if names_check(s, w, names, 12) == 0:
        return 0
    expected = find_signature(s, w, target)
    if expected == N:
        return refuse(w, 14)
    vector = edge_values(s, w, names)
    if vector == N:
        return 0
    count = total(s, names)
    if same_types(s, w, vector, count, expected) == 0:
        return refuse(w, 17)
    i = 0
    while i < count:
        put(w, vector + i * 8, env_values(s, w, get(w, vector + i * 8)))
        i = i + 1
    put(w, S + destination, target)
    put(w, S + destination + 8, vector)
    put(w, S + destination + 16, count)
    return 0

def lower_return(s:readbuf, w:mutbuf, term:u64) -> u64:
    if keys(s, term, 65, 2) == 0:
        return refuse(w, 18)
    names = field(s, term, 64)
    if names_check(s, w, names, 19) == 0:
        return 0
    count = total(s, names)
    vector = allocate(w, count * 8)
    if get(w, S + 32) != 0:
        return 0
    at = names + 24
    i = 0
    while i < count:
        index = admitted_value(s, w, at)
        if index == N:
            return 0
        put(w, vector + i * 8, index)
        at = end(s, at)
        i = i + 1
    if same_types(s, w, vector, count, element(s, 0, 5)) == 0:
        return refuse(w, 21)
    i = 0
    while i < count:
        index = get(w, vector + i * 8)
        sid = value_id(s, w, index)
        if get(w, VF + sid * 8) != 0:
            return refuse(w, 7)
        if linear(s, typename(s, w, env_type(s, w, index))) != 0:
            put(w, VF + sid * 8, 1)
        i = i + 1
    i = 0
    while i < get(w, S + 56):
        if live(s, w, i) != 0:
            return refuse(w, 22)
        i = i + 1
    i = 0
    while i < count:
        put(w, vector + i * 8, env_values(s, w, get(w, vector + i * 8)))
        i = i + 1
    put(w, S + 168, vector)
    put(w, S + 176, count)
    return 0

def lower(s:readbuf, w:mutbuf) -> u64:
    term = element(s, 0, 1)
    op = field(s, term, 1)
    if tag(s, term) != 6 or op == N or tag(s, op) != 4:
        put(w, S + 96, 0)
        return refuse(w, 1)
    code = op_id(s, op)
    put(w, S + 104, code)
    if code == 1:
        if keys(s, term, 7, 3) == 0:
            return refuse(w, 2)
        lower_edge(s, w, term, 1, 112)
    elif code == 2:
        if keys(s, term, 57, 4) == 0:
            return refuse(w, 3)
        cond = admitted_value(s, w, field(s, term, 8))
        if cond == N:
            return 0
        descriptor = typename(s, w, env_type(s, w, cond))
        if kind_id(s, element(s, descriptor, 0)) != 1 or text_is(s, element(s, flat_node(s, descriptor), 0), L_bool) == 0:
            return refuse(w, 8)
        put(w, S + 160, element(s, env_values(s, w, cond), 0))
        lower_edge(s, w, field(s, term, 16), 0, 112)
        if get(w, S + 8) == 0 and get(w, S + 32) == 0:
            lower_edge(s, w, field(s, term, 32), 0, 136)
    elif code == 3:
        lower_return(s, w, term)
    elif code == 4:
        if keys(s, term, 129, 2) == 0:
            return refuse(w, 23)
        put(w, S + 184, term)
    elif code == 5:
        put(w, S + 88, 1)
    else:
        return refuse(w, 24)
    return 0

def render_edge(o:mutbuf, w:mutbuf, position:u64) -> u64:
    at = graph_begin(o, w, 6, 2)
    graph_string(o, w, L_target)
    graph_ref(o, w, get(w, S + position))
    graph_string(o, w, L_args)
    graph_concat(o, w, get(w, S + position + 8), get(w, S + position + 16))
    graph_end(o, w, at)
    return 0

def render(s:readbuf, o:mutbuf, w:mutbuf) -> u64:
    code = get(w, S + 104)
    if code == 4:
        graph_ref(o, w, get(w, S + 184))
        return 0
    count = 2
    if code == 1:
        count = 3
    if code == 2:
        count = 4
    at = graph_begin(o, w, 6, count)
    graph_string(o, w, L_op)
    if code == 1:
        graph_string(o, w, L_jump)
        graph_string(o, w, L_target)
        graph_ref(o, w, get(w, S + 112))
        graph_string(o, w, L_args)
        graph_concat(o, w, get(w, S + 120), get(w, S + 128))
    elif code == 2:
        graph_string(o, w, L_branch)
        graph_string(o, w, L_cond)
        graph_ref(o, w, get(w, S + 160))
        graph_string(o, w, L_then)
        render_edge(o, w, 112)
        graph_string(o, w, L_else)
        render_edge(o, w, 136)
    else:
        graph_string(o, w, L_ret)
        graph_string(o, w, L_values)
        graph_concat(o, w, get(w, S + 168), get(w, S + 176))
    graph_end(o, w, at)
    return 0
'''


def source_program():
    literals = {'L_' + word: packed(word) for word in
                ('bool', 'target', 'args', 'op', 'jump', 'branch', 'cond',
                 'then', 'else', 'ret', 'values')}

    class Expand(ast.NodeTransformer):
        def visit_Name(self, node):
            return ast.Constant(CONSTANTS[node.id]) if node.id in CONSTANTS else node

        def visit_Call(self, node):
            node = self.generic_visit(node)
            args = []
            for arg in node.args:
                if isinstance(arg, ast.Name) and arg.id in literals:
                    args.extend(ast.Constant(value) for value in literals[arg.id])
                else:
                    args.append(arg)
            node.args = args
            return node

    own = ast.parse(BODY)
    common = {'validate', 'word', 'put', 'get', 'tag', 'size_of', 'end', 'total',
              'element', 'text_is', 'same_text'}
    text = TRANSPORT_SOURCE.replace('    DISPATCH', '    pass').replace('1048576', '8388608')
    own.body.extend(node for node in ast.parse(text).body
                    if isinstance(node, ast.FunctionDef) and node.name in common)
    shared = {'unsigned', 'truth', 'prefix', 'name_status', 'name_check', 'hash_name',
              'field', 'typename', 'flat_node', 'type_width', 'linear', 'type_equal',
              'env_type', 'env_values', 'env_lookup', 'refuse', 'allocate'}
    text = MATCH_BODY.replace('if value > 262144:', 'if value > 524288:')
    own.body.extend(node for node in ast.parse(text).body
                    if isinstance(node, ast.FunctionDef) and node.name in shared)
    own.body.extend(ast.parse(GRAPH_BODY).body)
    own.body.extend(node for node in ast.parse(HELPER_BODY).body
                    if isinstance(node, ast.FunctionDef) and node.name in {'append_byte', 'emit'})
    own = Expand().visit(own)
    suffix = []
    for function, values in [
        ('type_id', enumerate(PRIMITIVES, 1)),
        ('kind_id', enumerate(('primitive', 'record', 'enum', 'task', 'partial_record'), 1)),
        ('field_id', zip((1, 2, 4, 8, 16, 32, 64, 128),
                         ('op', 'target', 'args', 'cond', 'then', 'else', 'values', 'code'))),
        ('op_id', enumerate(('jump', 'branch', 'ret', 'trap', 'match'), 1)),
    ]:
        suffix.append('def ' + function + '(s:readbuf, node:u64) -> u64:')
        for identifier, value in values:
            suffix += ['    if text_is(s, node, ' + ', '.join(map(str, packed(value))) + ') != 0:',
                       '        return ' + str(identifier)]
        suffix += ['    return 0']
    return ast.unparse(ast.fix_missing_locations(own)) + '\n' + '\n'.join(suffix) + '\n'


def document():
    nodes = ast.parse(source_program()).body
    assert len({node.name for node in nodes}) == len(nodes)
    names = {node.name: 'f' + str(i) for i, node in enumerate(nodes)}
    signatures = {node.name: ([arg.annotation.id for arg in node.args.args], node.returns.id) for node in nodes}
    total = total_scalar_functions(nodes)
    functions = []
    for node in nodes:
        builder = Builder(node, names, signatures, total)
        builder.statements(node.body)
        functions.append({'name': names[node.name], 'params': [builder.param(p) for p in builder.params],
            'returns': [builder.returns], 'effects': ['read', 'write', 'trap'],
            'entry': 'b0', 'blocks': builder.blocks})
    return compact_authoring_cfg({'schema': 'hepta.hia.program.v8',
                                 'module': 'nominal_terminators', 'functions': functions})


if __name__ == '__main__':
    target = Path(__file__).resolve().parents[1] / 'examples/hia_bootstrap/nominal_terminators.hepta'
    target.write_text(render_assembly(document()))
    print(target.name, target.stat().st_size)

"""Author the complete public object/text normalization coordinator in HIA.

Foreign requests observe exact builtin objects or call the two explicitly held
HIA byte codecs.  Snapshot traversal, cycle/queued-node admission, structure
order, Unicode/decimal accounting, sorting and serialization live in this
program.  No smaller object, integer or serialized-byte profile is introduced.
"""
from __future__ import annotations

import ast
from pathlib import Path

from hepta.hia_agent_assembly import render_assembly
from tools.generate_hia_selfhost import Builder, compact_authoring_cfg, total_scalar_functions
from tools.hia_program_normalization_materialize import (
    FRAGMENT_FUNCTIONS, exported_bindings, fragment_functions,
)
from tools.hia_program_normalization_encoding import BODY as ENCODING

MAX_BYTES = 8 << 20
MAX_NODES = 262144
NODE_BASE = 4096
NODE_CAPACITY = MAX_NODES * 2 + 65
POOL_BASE = NODE_BASE + NODE_CAPACITY * 128
BINARY_BASE = POOL_BASE + MAX_BYTES
DECIMAL_BASE = BINARY_BASE + MAX_BYTES // 2 + 16
WORKSPACE_BYTES = 128 << 20
ENCODE_STACK_BASE = DECIMAL_BASE + MAX_BYTES * 2
CONSTANTS = {
    'MAX_BYTES': MAX_BYTES, 'MAX_NODES': MAX_NODES, 'MAX_DEPTH': 64,
    'NODE_BASE': NODE_BASE, 'NODE_CAPACITY': NODE_CAPACITY, 'POOL_BASE': POOL_BASE, 'BINARY_BASE': BINARY_BASE,
    'DECIMAL_BASE': DECIMAL_BASE, 'WORKSPACE_BYTES': WORKSPACE_BYTES,
    'ENCODE_STACK_BASE': ENCODE_STACK_BASE, 'PRE_STACK_BASE': 1024,
    'NONE': (1 << 64) - 1, 'BAD_ABI': 0xffffffff,
    'INPUT_MAGIC': int.from_bytes(b'HIANORQ2', 'little'),
    'STATE_MAGIC': int.from_bytes(b'HIANORS2', 'little'),
    'OUTPUT_MAGIC': int.from_bytes(b'HIANORP2', 'little'),
}

# Fixed state fields are byte offsets. Nodes contain kind/opaque handle,
# parent/next/previous/first/last/count, key handle/key offset/key bytes,
# scalar offset/scalar bytes and three reserved/capture words.
for index, name in enumerate(('MAGIC', 'NONCE_LO', 'NONCE_HI', 'SEQUENCE', 'ACTION',
        'LAUNCHED', 'PHASE', 'ERROR', 'CALLER', 'NODES', 'SNAP_COUNT', 'SNAP_QUEUED',
        'CURRENT', 'AVAILABLE', 'ITERATOR', 'STRUCT_COUNT', 'STRUCT_QUEUED', 'SIZE',
        'POOL_USED', 'KEY_NODE', 'STRING_NODE', 'STRING_KEY', 'STRING_LENGTH',
        'STRING_OFFSET', 'STRING_SIZE', 'STRING_START', 'RAW_LENGTH', 'RAW_OFFSET',
        'RAW_BYTES', 'OUT_CURSOR', 'INT_BITS', 'INT_NEGATIVE', 'DECIMAL_COUNT',
        'DIGITS', 'REQUEST_HANDLE', 'REQUEST_A', 'REQUEST_B', 'ROOT_HANDLE', 'TYPE_HANDLE', 'DECLARED', 'DIRECT_KEY', 'FINAL_SIZE', 'MAT_BASE', 'MAT_POSITION',
        'MAT_DEPTH', 'MAT_COUNT', 'MAT_ROOT', 'MAT_KIND', 'MAT_START', 'MAT_LENGTH',
        'MAT_VALUE', 'EXPECT_COUNT', 'E_DEPTH', 'E_OVERFLOW', 'E_SURROGATE', 'E_NODE',
        'E_HANDLE', 'E_KEY', 'E_KIND', 'E_CAPTURE', 'E_PUSH_MODE', 'E_STRING_LENGTH',
        'E_STRING_OFFSET', 'E_BITS', 'E_LIMIT', 'E_BINARY', 'E_DECIMAL', 'E_INTEGER_BYTES',
        'E_SCOPE_CURRENT', 'E_SCOPE_SEQUENCE', 'E_PENDING_ERROR', 'FOREIGN_ERROR',
        'STAGE', 'PRE_DEPTH', 'PRE_NODE', 'PRE_NEXT', 'PRE_CLEANUP', 'E_OUTPUT_RESUME',
        'PYTHON_NOTES', 'E_NOTE_OLD_ERROR')):
    CONSTANTS['H_' + name] = index * 8


class NormalizationBuilder(Builder):
    def expr(self, value):
        if isinstance(value, ast.BinOp) and isinstance(value.op, (ast.FloorDiv, ast.Mod)):
            left, right = self.expr(value.left), self.expr(value.right)
            if left[1] != 'u64' or right[1] != 'u64':
                raise ValueError('normalization division/remainder requires u64')
            return self.op('int.div.checked' if isinstance(value.op, ast.FloorDiv)
                           else 'int.rem.checked', [left, right], 'u64')
        return super().expr(value)


SOURCE = r'''
def normalize_state(s:readbuf, o:mutbuf, w:mutbuf) -> u32:
    if length(s) < 128 or length(o) < MAX_BYTES + 64 or length(w) < WORKSPACE_BYTES:
        return BAD_ABI
    if norm_read(s, 0, 8) != INPUT_MAGIC or norm_read(s, 80, 8) != length(s) - 128:
        return BAD_ABI
    if norm_read(s, 88, 8) != 0 or norm_read(s, 96, 8) != 0 or norm_read(s, 104, 8) != 0 or norm_read(s, 112, 8) != 0 or norm_read(s, 120, 8) != 0:
        return BAD_ABI
    event = norm_read(s, 8, 8)
    if event == 0:
        if get(w, H_MAGIC) != 0 or length(s) != 128 or norm_read(s, 32, 8) != 0 or norm_read(s, 40, 8) != 0 or norm_read(s, 48, 8) != 0 or norm_read(s, 72, 8) > 1:
            return BAD_ABI
        handle = norm_read(s, 56, 8)
        digits = norm_read(s, 64, 8)
        if handle == 0 or (digits != 0 and digits < 640):
            return BAD_ABI
        fill_range(w, 0, 4096, 0)
        put(w, H_MAGIC, STATE_MAGIC)
        put(w, H_NONCE_LO, norm_read(s, 16, 8))
        put(w, H_NONCE_HI, norm_read(s, 24, 8))
        put(w, H_DIGITS, digits)
        put(w, H_PYTHON_NOTES, norm_read(s, 72, 8))
        put(w, H_ROOT_HANDLE, handle)
        put(w, H_NODES, 1)
        norm_node(w, 0, handle, NONE, 0)
        put(w, H_PHASE, 100)
        return norm_issue(w, o, 10, handle, 0, 0)
    if get(w, H_MAGIC) != STATE_MAGIC or get(w, H_PHASE) == 99:
        return BAD_ABI
    if norm_read(s, 16, 8) != get(w, H_NONCE_LO) or norm_read(s, 24, 8) != get(w, H_NONCE_HI):
        return BAD_ABI
    if norm_read(s, 32, 8) != get(w, H_SEQUENCE) or norm_read(s, 40, 8) != get(w, H_ACTION):
        return BAD_ABI
    if event == 1:
        if get(w, H_LAUNCHED) != 0 or length(s) != 128 or norm_read(s, 48, 8) != 0 or norm_read(s, 56, 8) != 0 or norm_read(s, 64, 8) != 0 or norm_read(s, 72, 8) != 0:
            return BAD_ABI
        put(w, H_LAUNCHED, 1)
        return norm_frame(w, o, 0)
    if event != 2 or get(w, H_LAUNCHED) != 1:
        return BAD_ABI
    put(w, H_LAUNCHED, 0)
    result = norm_widen(norm_ack(s, o, w))
    while result == 0:
        result = norm_widen(norm_drive(w, o))
    return result

def norm_widen(value:u32) -> u64:
    return value

def norm_read(s:readbuf, at:u64, count:u64) -> u64:
    value = 0
    i = 0
    while i < count:
        value = value | (byte(s, at + i) << (i * 8))
        i = i + 1
    return value

def get(w:mutbuf, at:u64) -> u64:
    value = 0
    i = 0
    while i < 8:
        value = value | (byte(w, at + i) << (i * 8))
        i = i + 1
    return value

def put(w:mutbuf, at:u64, value:u64) -> u64:
    i = 0
    while i < 8:
        store(w, at + i, (value >> (i * 8)) & 255)
        i = i + 1
    return 0

def norm_record(node:u64) -> u64:
    return NODE_BASE + node * 128

def norm_node(w:mutbuf, node:u64, handle:u64, parent:u64, key:u64) -> u64:
    at = norm_record(node)
    fill_range(w, at, 128, 0)
    put(w, at + 8, handle)
    put(w, at + 16, parent)
    put(w, at + 24, NONE)
    put(w, at + 32, NONE)
    put(w, at + 40, NONE)
    put(w, at + 48, NONE)
    put(w, at + 64, key)
    return 0

def norm_frame(w:mutbuf, o:mutbuf, payload:u64) -> u32:
    put(o, 0, OUTPUT_MAGIC)
    put(o, 8, get(w, H_SEQUENCE))
    put(o, 16, get(w, H_ACTION))
    put(o, 24, get(w, H_ERROR))
    put(o, 32, get(w, H_REQUEST_HANDLE))
    put(o, 40, get(w, H_REQUEST_A))
    put(o, 48, get(w, H_REQUEST_B))
    put(o, 56, payload)
    return 64 + payload

def norm_issue(w:mutbuf, o:mutbuf, action:u64, handle:u64, a:u64, b:u64) -> u32:
    if get(w, H_SEQUENCE) == NONE:
        return BAD_ABI
    put(w, H_SEQUENCE, get(w, H_SEQUENCE) + 1)
    put(w, H_ACTION, action)
    put(w, H_REQUEST_HANDLE, handle)
    put(w, H_REQUEST_A, a)
    put(w, H_REQUEST_B, b)
    return norm_frame(w, o, 0)

def norm_error(w:mutbuf, o:mutbuf, code:u64) -> u32:
    if get(w, H_STAGE) == 3 and get(w, H_E_SCOPE_CURRENT) != 0:
        return norm_encode_abort(w, o, code)
    return norm_error_final(w, o, code)

def norm_error_final(w:mutbuf, o:mutbuf, code:u64) -> u32:
    put(w, H_PHASE, 99)
    put(w, H_ACTION, 0)
    put(w, H_ERROR, code)
    put(w, H_REQUEST_HANDLE, choose(code == 20, get(w, H_FOREIGN_ERROR), 0))
    put(w, H_REQUEST_A, 0)
    put(w, H_REQUEST_B, 0)
    return norm_frame(w, o, 0)

def norm_done(w:mutbuf, o:mutbuf, size:u64) -> u32:
    put(w, H_PHASE, 99)
    put(w, H_ACTION, 0)
    put(w, H_REQUEST_HANDLE, get(w, H_MAT_ROOT))
    put(w, H_REQUEST_A, get(w, H_MAT_COUNT))
    put(w, H_REQUEST_B, get(w, H_DIGITS))
    return norm_frame(w, o, size)

def norm_schedule(w:mutbuf, phase:u64, node:u64) -> u32:
    put(w, H_PHASE, phase)
    put(w, H_CURRENT, node)
    return 0

def norm_drive(w:mutbuf, o:mutbuf) -> u32:
    phase = get(w, H_PHASE)
    if phase == 30:
        return norm_structure_visit(w, o, get(w, H_CURRENT))
    if phase == 31:
        return norm_structure_advance(w, o, get(w, H_CURRENT))
    if phase == 32:
        return norm_structure_descend(w, o)
    if phase == 33:
        return norm_key_next(w, o)
    if phase == 34:
        put(w, H_PRE_CLEANUP, 6)
        put(w, H_PHASE, 153)
        return norm_issue(w, o, 53, 0, 6, 0)
    if phase == 120:
        return norm_snapshot_resume(w, o)
    if phase == 250:
        return norm_encode_next(w, o)
    if phase == 310:
        return norm_mat_next(w, o)
    return BAD_ABI

def norm_depth(w:mutbuf, node:u64) -> u64:
    depth = 0
    parent = get(w, norm_record(node) + 16)
    while parent != NONE:
        depth = depth + 1
        parent = get(w, norm_record(parent) + 16)
    return depth

def norm_cycle(w:mutbuf, node:u64) -> u64:
    handle = get(w, norm_record(node) + 8)
    parent = get(w, norm_record(node) + 16)
    while parent != NONE:
        if get(w, norm_record(parent) + 8) == handle:
            return 1
        parent = get(w, norm_record(parent) + 16)
    return 0

def norm_snapshot_visit(w:mutbuf, o:mutbuf, node:u64) -> u32:
    put(w, H_CURRENT, node)
    put(w, H_PHASE, 102)
    return norm_issue(w, o, 53, get(w, norm_record(node) + 8), 1, 0)

def norm_snapshot_after_pin(w:mutbuf, o:mutbuf) -> u32:
    node = get(w, H_CURRENT)
    put(w, H_SNAP_COUNT, get(w, H_SNAP_COUNT) + 1)
    put(w, H_SNAP_QUEUED, get(w, H_SNAP_QUEUED) - 1)
    if get(w, H_SNAP_COUNT) > MAX_NODES or norm_depth(w, node) > MAX_DEPTH:
        return norm_error(w, o, 4)
    put(w, H_PHASE, 10)
    return norm_issue(w, o, 10, get(w, norm_record(node) + 8), 1, 0)

def norm_snapshot_kind(s:readbuf, w:mutbuf, o:mutbuf) -> u32:
    node = get(w, H_CURRENT)
    at = norm_record(node)
    container = norm_read(s, 56, 8)
    held_type = norm_read(s, 64, 8)
    kind = norm_read(s, 72, 8)
    if length(s) != 128 or container > 1 or held_type == 0 or kind > 8:
        return BAD_ABI
    put(w, at, kind)
    put(w, H_TYPE_HANDLE, held_type)
    if container != 0:
        # The captured type's equality chooses membership; the dict arm is
        # still an identity test. Every other admitted container is copied as
        # a plain list, exactly as the original snapshot.
        put(w, at, choose(kind == 6, 6, 5))
        put(w, at + 104, 1)
        if norm_cycle(w, node) != 0:
            return norm_error(w, o, 5)
        put(w, H_AVAILABLE, MAX_NODES - get(w, H_SNAP_COUNT) - get(w, H_SNAP_QUEUED))
        return norm_pre_begin(w, o, 103)
    # This second tuple-membership expression is independently observable.
    put(w, H_PHASE, 101)
    return norm_issue(w, o, 11, held_type, 0, 0)

def norm_snapshot_advance(w:mutbuf, o:mutbuf, node:u64) -> u32:
    put(w, H_PRE_NODE, get(w, norm_record(node) + 16))
    put(w, H_PRE_NEXT, get(w, norm_record(node) + 24))
    return norm_schedule(w, 120, node)

def norm_capture_next(w:mutbuf, o:mutbuf) -> u32:
    put(w, H_PHASE, 13)
    return norm_issue(w, o, 4, get(w, H_ITERATOR), get(w, norm_record(get(w, H_CURRENT))), 0)

def norm_capture(s:readbuf, o:mutbuf, w:mutbuf) -> u32:
    status = norm_read(s, 48, 8)
    at = norm_record(get(w, H_CURRENT))
    count = get(w, at + 56)
    if length(s) != 128 or status > 2:
        return BAD_ABI
    if status == 2:
        return norm_error(w, o, 10)
    if status == 0:
        put(w, H_SNAP_QUEUED, get(w, H_SNAP_QUEUED) + count)
        put(w, H_PHASE, 104)
        return norm_issue(w, o, 52, get(w, H_ITERATOR), get(w, H_E_SCOPE_CURRENT), 0)
    if get(w, at) == 6 and norm_read(s, 72, 8) != 4:
        return norm_error(w, o, 7)
    if count >= get(w, H_AVAILABLE):
        return norm_error(w, o, choose(get(w, at) == 6, 8, 9))
    child = get(w, H_NODES)
    if child >= MAX_NODES or norm_read(s, 56, 8) == 0:
        return BAD_ABI
    key = 0
    if get(w, at) == 6:
        key = norm_read(s, 64, 8)
        if key == 0:
            return BAD_ABI
    norm_node(w, child, norm_read(s, 56, 8), get(w, H_CURRENT), key)
    previous = get(w, at + 48)
    if previous == NONE:
        put(w, at + 40, child)
    else:
        put(w, norm_record(previous) + 24, child)
    put(w, norm_record(child) + 32, previous)
    put(w, at + 48, child)
    put(w, at + 56, count + 1)
    put(w, H_NODES, child + 1)
    if key != 0:
        put(w, H_PHASE, 106)
        return norm_issue(w, o, 56, key, 0, 0)
    return norm_capture_next(w, o)

def norm_structure_begin(w:mutbuf, o:mutbuf) -> u32:
    put(w, H_STAGE, 2)
    put(w, H_STRUCT_COUNT, 0)
    put(w, H_STRUCT_QUEUED, 1)
    put(w, H_DECLARED, 1)
    return norm_schedule(w, 30, 0)

def norm_structure_visit(w:mutbuf, o:mutbuf, node:u64) -> u32:
    put(w, H_CURRENT, node)
    handle = get(w, norm_record(node) + 8)
    if get(w, norm_record(node) + 104) == 1:
        handle = 0
    put(w, H_PHASE, 147)
    return norm_issue(w, o, 53, handle, 6, 0)

def norm_structure_after_pin(w:mutbuf, o:mutbuf) -> u32:
    node = get(w, H_CURRENT)
    put(w, H_STRUCT_COUNT, get(w, H_STRUCT_COUNT) + 1)
    if get(w, H_STRUCT_COUNT) > MAX_NODES or norm_depth(w, node) > MAX_DEPTH:
        return norm_error(w, o, 12)
    at = norm_record(node)
    kind = get(w, at)
    if get(w, at + 104) != 1 and kind == 8:
        put(w, H_PHASE, 140)
        return norm_issue(w, o, 10, get(w, at + 8), 2, 0)
    put(w, H_PHASE, 148)
    return norm_issue(w, o, 53, 0, 7, 0)

def norm_structure_kind(w:mutbuf, o:mutbuf, kind:u64) -> u32:
    node = get(w, H_CURRENT)
    at = norm_record(node)
    if kind == 5 or kind == 6:
        count = get(w, at + 56)
        if count > MAX_NODES - get(w, H_DECLARED):
            return norm_error(w, o, 13)
        put(w, H_DECLARED, get(w, H_DECLARED) + count)
        put(w, H_SIZE, get(w, H_SIZE) + 2 + choose(count == 0, 0, count - 1))
        if kind == 6:
            put(w, H_SIZE, get(w, H_SIZE) + count)
            put(w, H_KEY_NODE, get(w, at + 40))
            return norm_schedule(w, 33, node)
        return norm_schedule(w, 32, node)
    if kind == 4:
        return norm_string_begin(w, o, node, 0)
    if kind == 3:
        put(w, H_PHASE, 22)
        return norm_issue(w, o, 7, get(w, at + 8), 0, 0)
    if kind > 4:
        return norm_error(w, o, 16)
    put(w, H_SIZE, get(w, H_SIZE) + choose(kind == 1, 5, 4))
    if get(w, H_SIZE) > MAX_BYTES:
        return norm_error(w, o, 18)
    return norm_schedule(w, 31, node)

def norm_structure_descend(w:mutbuf, o:mutbuf) -> u32:
    if get(w, H_SIZE) > MAX_BYTES:
        return norm_error(w, o, 18)
    node = get(w, H_CURRENT)
    at = norm_record(node)
    if get(w, at + 104) == 2:
        remaining = get(w, at + 120)
        if remaining != 0:
            if get(w, H_STRUCT_COUNT) >= MAX_NODES or norm_depth(w, node) >= MAX_DEPTH:
                return norm_error(w, o, 12)
            put(w, at + 120, remaining - 1)
            put(w, H_PHASE, 146)
            return norm_issue(w, o, 21, get(w, at + 112), remaining - 1, 0)
        put(w, H_PHASE, 151)
        return norm_issue(w, o, 53, 0, 6, 0)
    child = get(w, at + 48)
    if child != NONE:
        return norm_schedule(w, 30, child)
    return norm_schedule(w, 31, node)

def norm_structure_advance(w:mutbuf, o:mutbuf, node:u64) -> u32:
    while node != NONE:
        parent = get(w, norm_record(node) + 16)
        if parent != NONE:
            if get(w, norm_record(parent) + 104) == 2:
                return norm_schedule(w, 32, parent)
        previous = get(w, norm_record(node) + 32)
        if previous != NONE:
            return norm_schedule(w, 30, previous)
        node = parent
    return norm_schedule(w, 34, 0)

def norm_key_next(w:mutbuf, o:mutbuf) -> u32:
    key_node = get(w, H_KEY_NODE)
    if key_node == NONE:
        return norm_schedule(w, 32, get(w, H_CURRENT))
    return norm_string_begin(w, o, key_node, 1)

def norm_string_begin(w:mutbuf, o:mutbuf, node:u64, key:u64) -> u32:
    put(w, H_STRING_NODE, node)
    put(w, H_STRING_KEY, key)
    put(w, H_PHASE, 20)
    handle = get(w, norm_record(node) + 8)
    if key == 1:
        handle = get(w, norm_record(node) + 64)
    if key == 2:
        handle = get(w, H_DIRECT_KEY)
    return norm_issue(w, o, 2, handle, 0, 0)

def norm_string_next(w:mutbuf, o:mutbuf) -> u32:
    remaining = get(w, H_STRING_LENGTH) - get(w, H_STRING_OFFSET)
    if remaining == 0:
        return norm_string_done(w, o)
    if remaining > 4096:
        remaining = 4096
    handle = get(w, norm_record(get(w, H_STRING_NODE)) + 8)
    if get(w, H_STRING_KEY) == 1:
        handle = get(w, norm_record(get(w, H_STRING_NODE)) + 64)
    if get(w, H_STRING_KEY) == 2:
        handle = get(w, H_DIRECT_KEY)
    put(w, H_PHASE, 21)
    return norm_issue(w, o, 5, handle, get(w, H_STRING_OFFSET), remaining)

def norm_string_done(w:mutbuf, o:mutbuf) -> u32:
    at = norm_record(get(w, H_STRING_NODE))
    size = get(w, H_POOL_USED) - get(w, H_STRING_START)
    offset = 88
    if get(w, H_STRING_KEY) == 1:
        offset = 72
    if get(w, H_STRING_KEY) != 2:
        put(w, at + offset, POOL_BASE + get(w, H_STRING_START))
        put(w, at + offset + 8, size)
    put(w, H_SIZE, get(w, H_SIZE) + get(w, H_STRING_SIZE))
    if get(w, H_STRING_KEY) == 2:
        return norm_structure_key_request(w, o)
    if get(w, H_STRING_KEY) == 1:
        put(w, H_KEY_NODE, get(w, at + 24))
        return norm_schedule(w, 33, get(w, H_CURRENT))
    return norm_schedule(w, 31, get(w, H_CURRENT))

def norm_structure_cycle(w:mutbuf, node:u64) -> u64:
    identity = get(w, norm_record(node) + 8)
    parent = get(w, norm_record(node) + 16)
    while parent != NONE:
        at = norm_record(parent)
        # Detached snapshot containers have fresh identities. They cannot be
        # the same foreign object as a retained opaque leaf.
        if get(w, at + 104) != 1 and get(w, at + 8) == identity:
            return 1
        parent = get(w, at + 16)
    return 0

def norm_structure_key_request(w:mutbuf, o:mutbuf) -> u32:
    put(w, H_PHASE, 143)
    return norm_issue(w, o, 18, get(w, H_ITERATOR), 0, 0)

def norm_structure_capture_request(w:mutbuf, o:mutbuf) -> u32:
    put(w, H_PHASE, 145)
    at = norm_record(get(w, H_CURRENT))
    return norm_issue(w, o, 20, get(w, at + 8), get(w, at), 0)

def norm_structure_ack(s:readbuf, o:mutbuf, w:mutbuf) -> u32:
    phase = get(w, H_PHASE)
    node = get(w, H_CURRENT)
    at = norm_record(node)
    if length(s) != 128:
        return BAD_ABI
    if phase == 143:
        status = norm_read(s, 48, 8)
        if status == 0:
            return norm_structure_capture_request(w, o)
        if status != 1 or norm_read(s, 56, 8) == 0:
            return BAD_ABI
        if norm_read(s, 64, 8) != 4:
            return norm_error(w, o, 14)
        put(w, H_DIRECT_KEY, norm_read(s, 56, 8))
        return norm_string_begin(w, o, node, 2)
    if norm_read(s, 48, 8) != 0:
        return BAD_ABI
    if phase == 140:
        member = norm_read(s, 56, 8)
        kind = norm_read(s, 72, 8)
        if member > 1 or norm_read(s, 64, 8) == 0 or kind > 8:
            return BAD_ABI
        if member == 0:
            put(w, at, kind)
            return norm_structure_kind(w, o, kind)
        if norm_structure_cycle(w, node) != 0:
            return norm_error(w, o, 19)
        put(w, at, choose(kind == 6, 6, 5))
        put(w, at + 104, 2)
        return norm_pre_begin(w, o, 149)
    if phase == 141:
        count = norm_read(s, 56, 8)
        if count > MAX_NODES - get(w, H_DECLARED):
            return norm_error(w, o, 13)
        put(w, H_DECLARED, get(w, H_DECLARED) + count)
        put(w, at + 56, count)
        put(w, H_SIZE, get(w, H_SIZE) + 2 + choose(count == 0, 0, count - 1))
        if get(w, at) == 6:
            put(w, H_SIZE, get(w, H_SIZE) + count)
            put(w, H_PHASE, 142)
            return norm_issue(w, o, 17, get(w, at + 8), 0, 0)
        return norm_structure_capture_request(w, o)
    if phase == 142:
        if norm_read(s, 56, 8) == 0:
            return BAD_ABI
        put(w, H_ITERATOR, norm_read(s, 56, 8))
        return norm_structure_key_request(w, o)
    if phase == 145:
        if norm_read(s, 56, 8) == 0:
            return BAD_ABI
        put(w, at + 112, norm_read(s, 56, 8))
        put(w, at + 120, norm_read(s, 64, 8))
        return norm_schedule(w, 32, node)
    if phase == 146:
        child = get(w, H_NODES)
        if child >= NODE_CAPACITY or norm_read(s, 56, 8) == 0:
            return BAD_ABI
        norm_node(w, child, norm_read(s, 56, 8), node, 0)
        put(w, norm_record(child), 8)
        put(w, H_NODES, child + 1)
        return norm_schedule(w, 30, child)
    return BAD_ABI

def norm_raw_next(w:mutbuf, o:mutbuf) -> u32:
    remaining = get(w, H_RAW_LENGTH) - get(w, H_RAW_OFFSET)
    if remaining == 0:
        put(w, H_PHASE, 4)
        return norm_issue(w, o, 9, 0, get(w, H_RAW_BYTES), 0)
    if remaining > 4096:
        remaining = 4096
    put(w, H_PHASE, 3)
    return norm_issue(w, o, 6, get(w, H_ROOT_HANDLE), get(w, H_RAW_OFFSET), remaining)

def norm_pre_begin(w:mutbuf, o:mutbuf, phase:u64) -> u32:
    sequence = get(w, H_E_SCOPE_SEQUENCE)
    if sequence == NONE or get(w, H_PRE_DEPTH) > MAX_DEPTH:
        return BAD_ABI
    put(w, H_PHASE, phase)
    return norm_issue(w, o, 50, 0, sequence + 1, get(w, H_E_SCOPE_CURRENT))

def norm_pre_enter(s:readbuf, w:mutbuf) -> u64:
    scope = norm_read(s, 56, 8)
    depth = get(w, H_PRE_DEPTH)
    if scope != get(w, H_E_SCOPE_SEQUENCE) + 1 or scope != get(w, H_REQUEST_A) or depth > MAX_DEPTH:
        return 0
    frame = PRE_STACK_BASE + depth * 32
    put(w, frame, get(w, H_CURRENT))
    put(w, frame + 8, scope)
    put(w, frame + 16, get(w, H_E_SCOPE_CURRENT))
    put(w, frame + 24, 0)
    put(w, H_PRE_DEPTH, depth + 1)
    put(w, H_E_SCOPE_SEQUENCE, scope)
    put(w, H_E_SCOPE_CURRENT, scope)
    return 1

def norm_pre_end(w:mutbuf, o:mutbuf, phase:u64) -> u32:
    depth = get(w, H_PRE_DEPTH)
    if depth == 0:
        return BAD_ABI
    frame = PRE_STACK_BASE + (depth - 1) * 32
    if get(w, frame) != get(w, H_CURRENT) or get(w, frame + 8) != get(w, H_E_SCOPE_CURRENT):
        return BAD_ABI
    put(w, H_PHASE, phase)
    return norm_issue(w, o, 51, 0, get(w, frame + 8), get(w, frame + 16))

def norm_pre_leave(s:readbuf, w:mutbuf) -> u64:
    depth = get(w, H_PRE_DEPTH)
    if depth == 0:
        return 0
    frame = PRE_STACK_BASE + (depth - 1) * 32
    parent = norm_read(s, 56, 8)
    if parent != get(w, H_REQUEST_B) or parent != get(w, frame + 16):
        return 0
    put(w, H_PRE_DEPTH, depth - 1)
    put(w, H_E_SCOPE_CURRENT, parent)
    return 1

def norm_snapshot_resume(w:mutbuf, o:mutbuf) -> u32:
    node = get(w, H_PRE_NODE)
    if node == NONE:
        if get(w, H_PRE_DEPTH) != 0 or get(w, H_E_SCOPE_CURRENT) != 0:
            return BAD_ABI
        put(w, H_PRE_CLEANUP, 1)
        put(w, H_PHASE, 109)
        return norm_issue(w, o, 53, 0, 1, 0)
    put(w, H_CURRENT, node)
    put(w, H_PHASE, 107)
    return norm_issue(w, o, 53, get(w, norm_record(node) + 8), 5, 0)

def norm_pre_snapshot_ack(s:readbuf, o:mutbuf, w:mutbuf) -> u32:
    phase = get(w, H_PHASE)
    node = get(w, H_CURRENT)
    if phase == 102:
        return norm_snapshot_after_pin(w, o)
    if phase == 103:
        if norm_pre_enter(s, w) == 0:
            return BAD_ABI
        put(w, H_PHASE, 11)
        return norm_issue(w, o, 2, get(w, norm_record(node) + 8), 0, 0)
    if phase == 104:
        put(w, H_PRE_NODE, node)
        put(w, H_PRE_NEXT, get(w, norm_record(node) + 40))
        return norm_schedule(w, 120, node)
    if phase == 105:
        return norm_snapshot_advance(w, o, node)
    if phase == 106:
        return norm_capture_next(w, o)
    if phase == 107:
        depth = get(w, H_PRE_DEPTH)
        if depth == 0:
            return BAD_ABI
        put(w, H_PHASE, 111)
        return norm_issue(w, o, 53, get(w, PRE_STACK_BASE + (depth - 1) * 32 + 24), 9, 0)
    if phase == 108:
        if norm_pre_leave(s, w) == 0:
            return BAD_ABI
        return norm_snapshot_advance(w, o, node)
    if phase == 109:
        slot = get(w, H_PRE_CLEANUP)
        if slot < 6:
            put(w, H_PRE_CLEANUP, slot + 1)
            target = slot + 1
            if target == 3:
                target = 9
            else:
                if target > 3:
                    target = target - 1
            return norm_issue(w, o, 53, 0, target, 0)
        if slot == 6:
            put(w, H_PRE_CLEANUP, 7)
            return norm_issue(w, o, 54, get(w, H_ROOT_HANDLE), 0, 0)
        if slot == 7:
            return norm_structure_begin(w, o)
    if phase >= 111 and phase <= 114:
        return norm_snapshot_iterator_ack(s, o, w)
    return BAD_ABI

def norm_snapshot_iterator_ack(s:readbuf, o:mutbuf, w:mutbuf) -> u32:
    phase = get(w, H_PHASE)
    depth = get(w, H_PRE_DEPTH)
    if depth == 0:
        return BAD_ABI
    frame = PRE_STACK_BASE + (depth - 1) * 32
    next_node = get(w, H_PRE_NEXT)
    if phase == 111:
        if next_node == NONE:
            put(w, H_PHASE, 114)
            return norm_issue(w, o, 53, 0, 16 + depth - 1, 0)
        if get(w, norm_record(get(w, H_CURRENT))) != 5:
            return norm_snapshot_visit(w, o, next_node)
        handle = get(w, norm_record(next_node) + 8)
        put(w, frame + 24, handle)
        put(w, H_PHASE, 112)
        return norm_issue(w, o, 53, handle, 16 + depth - 1, 0)
    if phase == 112:
        put(w, H_PHASE, 113)
        return norm_issue(w, o, 53, get(w, frame + 24), 9, 0)
    if phase == 113:
        if next_node == NONE:
            return BAD_ABI
        return norm_snapshot_visit(w, o, next_node)
    if phase == 114:
        return norm_pre_end(w, o, 108)
    return BAD_ABI

def norm_pre_structure_ack(s:readbuf, o:mutbuf, w:mutbuf) -> u32:
    phase = get(w, H_PHASE)
    node = get(w, H_CURRENT)
    if phase == 147:
        return norm_structure_after_pin(w, o)
    if phase == 148:
        return norm_structure_kind(w, o, get(w, norm_record(node)))
    if phase == 149:
        if norm_pre_enter(s, w) == 0:
            return BAD_ABI
        put(w, H_PHASE, 150)
        return norm_issue(w, o, 57, get(w, norm_record(node) + 8), get(w, H_E_SCOPE_CURRENT), 0)
    if phase == 150:
        put(w, H_PHASE, 141)
        return norm_issue(w, o, 2, get(w, norm_record(node) + 8), 0, 0)
    if phase == 151:
        return norm_pre_end(w, o, 152)
    if phase == 152:
        if norm_pre_leave(s, w) == 0:
            return BAD_ABI
        return norm_schedule(w, 31, node)
    if phase == 153:
        slot = get(w, H_PRE_CLEANUP)
        if slot < 8:
            put(w, H_PRE_CLEANUP, slot + 1)
            return norm_issue(w, o, 53, 0, slot + 1, 0)
        if slot == 8 and get(w, H_PRE_DEPTH) == 0 and get(w, H_E_SCOPE_CURRENT) == 0:
            return norm_encode_start(w, o)
    return BAD_ABI

def norm_ack(s:readbuf, o:mutbuf, w:mutbuf) -> u32:
    phase = get(w, H_PHASE)
    if phase == 237:
        return norm_encode_note_ack(s, o, w)
    if norm_read(s, 48, 8) == 3:
        if length(s) != 128 or norm_read(s, 56, 8) == 0 or norm_read(s, 64, 8) != 0 or norm_read(s, 72, 8) != 0:
            return BAD_ABI
        put(w, H_FOREIGN_ERROR, norm_read(s, 56, 8))
        # A transport scope handoff that raised must never be replayed. Its
        # actual foreign custody remains in the context until final cleanup.
        if (phase >= 203 and phase <= 208) or (phase >= 238 and phase <= 241):
            return norm_error_final(w, o, 20)
        return norm_error(w, o, 20)
    if phase >= 140 and phase <= 146:
        return norm_structure_ack(s, o, w)
    if phase >= 300 and phase <= 303:
        return norm_mat_ack(s, o, w)
    if phase >= 200 and phase <= 241:
        return norm_encode_ack(s, o, w)
    if phase == 13:
        return norm_capture(s, o, w)
    if phase == 12 and norm_read(s, 48, 8) == 2 and length(s) == 128:
        return norm_error(w, o, 10)
    if norm_read(s, 48, 8) != 0:
        return BAD_ABI
    if phase >= 102 and phase <= 114:
        if length(s) != 128:
            return BAD_ABI
        return norm_pre_snapshot_ack(s, o, w)
    if phase >= 147 and phase <= 153:
        if length(s) != 128:
            return BAD_ABI
        return norm_pre_structure_ack(s, o, w)
    if phase == 100:
        if length(s) != 128 or norm_read(s, 56, 8) > 1 or norm_read(s, 64, 8) != 0 or norm_read(s, 72, 8) > 8:
            return BAD_ABI
        put(w, H_CALLER, norm_read(s, 56, 8))
        put(w, H_PHASE, 1)
        return norm_issue(w, o, 1, get(w, H_ROOT_HANDLE), 0, 0)
    if phase == 101:
        if length(s) != 128 or norm_read(s, 56, 8) > 1:
            return BAD_ABI
        if norm_read(s, 56, 8) == 0 and get(w, norm_record(get(w, H_CURRENT))) != 0:
            return norm_error(w, o, 11)
        put(w, H_PHASE, 105)
        return norm_issue(w, o, 56, get(w, norm_record(get(w, H_CURRENT)) + 8), 0, 0)
    if phase == 10:
        return norm_snapshot_kind(s, w, o)
    if phase == 1:
        kind = norm_read(s, 56, 8)
        if kind > 8 or length(s) != 128:
            return BAD_ABI
        put(w, NODE_BASE, kind)
        if kind == 7 or kind == 4:
            put(w, H_PHASE, 2)
            return norm_issue(w, o, 2, get(w, H_ROOT_HANDLE), 0, 0)
        if get(w, H_CALLER) != 0:
            put(w, H_STAGE, 1)
            put(w, H_SNAP_COUNT, 0)
            put(w, H_SNAP_QUEUED, 1)
            return norm_snapshot_visit(w, o, 0)
        return norm_structure_begin(w, o)
    if phase == 2:
        size = norm_read(s, 56, 8)
        if length(s) != 128:
            return BAD_ABI
        if size > MAX_BYTES:
            return norm_error(w, o, 1)
        put(w, H_RAW_LENGTH, size)
        if get(w, NODE_BASE) == 7:
            put(w, H_RAW_BYTES, size)
            put(w, H_PHASE, 4)
            return norm_issue(w, o, 9, get(w, H_ROOT_HANDLE), size, 0)
        return norm_raw_next(w, o)
    if phase == 3:
        size = length(s) - 128
        if size > get(w, H_REQUEST_B) * 4:
            return BAD_ABI
        if size > MAX_BYTES - get(w, H_RAW_BYTES):
            return norm_error(w, o, 1)
        norm_copy(s, w, 128, POOL_BASE + get(w, H_RAW_BYTES), size)
        put(w, H_RAW_BYTES, get(w, H_RAW_BYTES) + size)
        put(w, H_RAW_OFFSET, get(w, H_RAW_OFFSET) + get(w, H_REQUEST_B))
        return norm_raw_next(w, o)
    if phase == 4:
        size = length(s) - 128
        count = norm_read(s, 56, 8)
        if size == 0 or size > get(w, H_RAW_BYTES) or count == 0 or count > MAX_NODES:
            return BAD_ABI
        norm_copy(s, o, 128, 64, size)
        put(w, H_EXPECT_COUNT, count)
        return norm_mat_start(w, o, size)
    if phase == 11:
        if length(s) != 128:
            return BAD_ABI
        if norm_read(s, 56, 8) > get(w, H_AVAILABLE):
            return norm_error(w, o, 6)
        put(w, H_PHASE, 12)
        return norm_issue(w, o, 3, get(w, norm_record(get(w, H_CURRENT)) + 8), get(w, norm_record(get(w, H_CURRENT))), 0)
    if phase == 12:
        if length(s) != 128 or norm_read(s, 56, 8) == 0:
            return BAD_ABI
        put(w, H_ITERATOR, norm_read(s, 56, 8))
        return norm_capture_next(w, o)
    if phase == 20:
        size = norm_read(s, 56, 8)
        if length(s) != 128:
            return BAD_ABI
        if get(w, H_SIZE) > MAX_BYTES - 2 or size > MAX_BYTES - get(w, H_SIZE) - 2:
            return norm_error(w, o, 18)
        put(w, H_STRING_LENGTH, size)
        put(w, H_STRING_OFFSET, 0)
        put(w, H_STRING_SIZE, 2)
        put(w, H_STRING_START, get(w, H_POOL_USED))
        return norm_string_next(w, o)
    if phase == 21:
        return norm_string_chunk(s, o, w)
    if phase == 22:
        return norm_integer_bits(s, o, w)
