        return norm_pool_byte(w, point)
    if point < 2048:
        norm_pool_byte(w, 192 | (point >> 6))
        return norm_pool_byte(w, 128 | (point & 63))
    if point < 65536:
        norm_pool_byte(w, 224 | (point >> 12))
        norm_pool_byte(w, 128 | ((point >> 6) & 63))
        return norm_pool_byte(w, 128 | (point & 63))
