    if length(s) != 128:
        return BAD_ABI
    bits = norm_read(s, 56, 8)
    if bits > MAX_BYTES * 4:
        return norm_error(w, o, 15)
    put(w, H_INT_BITS, bits)
    put(w, H_PHASE, 24)
    return norm_issue(w, o, 34, 0, 0, 0)

