    if length(s) != 128:
        return BAD_ABI
    digits = norm_read(s, 56, 8)
    if digits != 0 and digits < 640:
        return BAD_ABI
    put(w, H_DIGITS, digits)
    bits = get(w, H_INT_BITS)
