        norm_emit_byte(w, o, 97)
        norm_emit_byte(w, o, 108)
        norm_emit_byte(w, o, 115)
        return norm_emit_byte(w, o, 101)
    norm_emit_byte(w, o, 116)
    norm_emit_byte(w, o, 114)
    norm_emit_byte(w, o, 117)
    return norm_emit_byte(w, o, 101)

