    key_characters = 0
    keyed = 0
    if key_kind == 1:
        if key_digest_size != 64 or hexadecimal(s, key_digest_start, 64) == 0:
            return invalid(o, 1)
        key_characters = unicode_count(s, key_start, key_size)
