    if size == 0 or size > 64:
        return 0
    if size > 1 and byte(s, start) == 48:
        return 0
    i = 0
    while i < size:
        ch = byte(s, start + i)
        if ch < 48 or ch > 57:
            return 0
        i = i + 1
    return 1

