        i = i + 1
    return 1

def literal(s:readbuf, start:u64, size:u64, expected_size:u64, low:u64, high:u64) -> u64:
    if size != expected_size:
        return 0
    i = 0
    while i < size:
        if i < 8:
            expected = (low >> (i * 8)) & 255
        else:
            expected = (high >> ((i - 8) * 8)) & 255
        if byte(s, start + i) != expected:
            return 0
        i = i + 1
    return 1

