def same_input(s:readbuf, start:u64, w:mutbuf, target:u64, size:u64) -> u64:
    i = 0
    while i < size:
        if byte(s, start + i) != byte(w, target + i):
            return 0
        i = i + 1
    return 1

def copy_input(s:readbuf, start:u64, w:mutbuf, target:u64, size:u64) -> u64:
    i = 0
    while i < size:
        store(w, target + i, byte(s, start + i))
        i = i + 1
    return size

