        h = (h ^ byte(w, i + 1)) * 1099511628211
        h = (h ^ byte(w, i + 2)) * 1099511628211
        h = (h ^ byte(w, i + 3)) * 1099511628211
        h = (h ^ byte(w, i + 4)) * 1099511628211
        h = (h ^ byte(w, i + 5)) * 1099511628211
        h = (h ^ byte(w, i + 6)) * 1099511628211
        h = (h ^ byte(w, i + 7)) * 1099511628211
        i = i + 8
