    put(w, 120, checksum(w))
    return 0

def receipt(o:mutbuf, status:u64, action:u64, nonce:u64, sequence:u64, value:u64, required:u64) -> u64:
    put(o, 0, status)
    put(o, 8, action)
    put(o, 16, nonce)
    put(o, 24, sequence)
    put(o, 32, value)
    put(o, 40, required)
    return status

