    return status

def compare_names(w:mutbuf, left:u64, right:u64) -> u64:
    a = get(w, left)
    b = get(w, right)
    an = get(w, left + 8)
    bn = get(w, right + 8)
    i = 0
    while i < an and i < bn:
        x = byte(w, a + i)
        y = byte(w, b + i)
        if x < y:
            return 1
        if x > y:
            return 2
        i = i + 1
    if an < bn:
        return 1
    if an > bn:
        return 2
    return 0

def greater(w:mutbuf, left:u64, right:u64) -> u64:
    relation = compare_names(w, left, right)
    if relation == 2:
        return 1
    if relation == 0 and get(w, left + 16) > get(w, right + 16):
        return 1
    return 0

